import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Gesamttabelle der Epocheneinteilung","description":"","frontmatter":{},"headers":[],"relativePath":"de/70-纪元划分总表.md","filePath":"de/70-纪元划分总表.md","lastUpdated":1789183869000}'),d={name:"de/70-纪元划分总表.md"};function s(a,e,u,h,l,o){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="gesamttabelle-der-epocheneinteilung" tabindex="-1">Gesamttabelle der Epocheneinteilung <a class="header-anchor" href="#gesamttabelle-der-epocheneinteilung" aria-label="Permalink to &quot;Gesamttabelle der Epocheneinteilung&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>70</td></tr><tr><td>Modul</td><td>Historische Epochen und wichtige Ereignisse</td></tr><tr><td>Kernschlüsselwörter</td><td>Epocheneinteilung, historische Periodisierung, vierstufige Dimensionserhöhung, Zeitachse, Meilenstein</td></tr></tbody></table><h2 id="i-grundprinzipien-der-epocheneinteilung" tabindex="-1">I. Grundprinzipien der Epocheneinteilung <a class="header-anchor" href="#i-grundprinzipien-der-epocheneinteilung" aria-label="Permalink to &quot;I. Grundprinzipien der Epocheneinteilung&quot;">​</a></h2><p>Die historische Epocheneinteilung von Hengyuanzhou nimmt den Weg der vierstufigen Dimensionserhöhung als grundlegenden Rahmen und den Entwicklungsstand des Ankermechanismus als zentrale Periodisierungsgrundlage. Jede Epoche entspricht einer grundlegenden Veränderung in der Beziehung zwischen Zivilisation und Universum; die Grenzen zwischen den Epochen sind keine willkürlichen Zeitpunkte, sondern werden durch bedeutende Ereignisse von kosmischer Bedeutung markiert.</p><p>Die Epocheneinteilung folgt drei Prinzipien:</p><ul><li><strong>Prinzip der Dimensionserhöhungs-Entsprechung</strong>: Jede große Epoche entspricht einer Stufe im Weg der vierstufigen Dimensionserhöhung, und die unterteilten Perioden innerhalb einer Epoche entsprechen den wichtigsten Fortschritten innerhalb dieser Stufe</li><li><strong>Prinzip der Ereignismarkierung</strong>: Die Anfangs- und Endpunkte einer Epoche werden durch markante bedeutende Ereignisse bestimmt, nicht durch eine einfache gleichmäßige Zeitaufteilung</li><li><strong>Prinzip des Zivilisationszustands</strong>: Jede Epoche wird nach den zentralen Merkmalen der Zivilisation in dieser Periode benannt und spiegelt die Hauptwidersprüche und die Entwicklungsrichtung der Zeit wider</li></ul><h2 id="ii-gesamttabelle-der-historischen-epochen-von-hengyuanzhou" tabindex="-1">II. Gesamttabelle der historischen Epochen von Hengyuanzhou <a class="header-anchor" href="#ii-gesamttabelle-der-historischen-epochen-von-hengyuanzhou" aria-label="Permalink to &quot;II. Gesamttabelle der historischen Epochen von Hengyuanzhou&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epochennummer</th><th>Epochenname</th><th>Entsprechende Stufe der Dimensionserhöhung</th><th>Markierende Anfangs-End-Ereignisse</th><th>Zentrale Merkmale</th></tr></thead><tbody><tr><td>Erste Epoche</td><td>Vor-Anker-Ära</td><td>Vor der Dimensionserhöhung</td><td>Geburt des Universums→Erwachen der ersten Anker-Generation</td><td>Räuberische Kultivierung dominiert, zivilisatorische Brüche häufig</td></tr><tr><td>Zweite Epoche</td><td>Ära des Anker-Erwachens</td><td>Beginn der Realitätsgrundierung</td><td>Erwachen der ersten Anker-Generation→Unterzeichnung der Symbiose-Charta</td><td>Ankermechanismus etabliert, Keim des anti-räuberischen Denkens</td></tr><tr><td>Dritte Epoche</td><td>Periode der Etablierung des Symbiose-Systems</td><td>Realitätsgrundierung</td><td>Unterzeichnung der Symbiose-Charta→Vollständige Öffnung der dreihundert Systeme</td><td>Symbiose-System umgesetzt, soziale Rekonstruktion abgeschlossen</td></tr><tr><td>Vierte Epoche</td><td>Ära der Systemöffnung und -aktivierung</td><td>Beginn der technologischen Befähigung</td><td>Öffnung der dreihundert Systeme→Abschluss der 20%-Aktivierungsstrategie</td><td>Popularisierung der Kultivierung, Durchbrüche in der Gesetzestechnik</td></tr><tr><td>Fünfte Epoche</td><td>Ära der ersten Dimensionserhöhung</td><td>Technologische Befähigung→Bewusstseinsentwicklung</td><td>Erfolg der ersten Dimensionserhöhung→Gründung der Allrassen-Republik</td><td>Verifikation der zivilisatorischen Dimensionserhöhung, Durchbruch der Bewusstseinsdomänen-Schnittstelle</td></tr><tr><td>Sechste Epoche</td><td>Ära der Allrassen-Republik</td><td>Bewusstseinsentwicklung</td><td>Gründung der Allrassen-Republik→Beginn der interplanaren Erkundung</td><td>Vereinheitlichung des Allrassensystems, kollektive Bewusstseins-Symbiose</td></tr><tr><td>Siebte Epoche</td><td>Ära der interplanaren Erkundung</td><td>Bewusstseinsentwicklung→Interstellare Symbiose</td><td>Beginn der interplanaren Erkundung→Erster Aufbau des interstellaren Netzwerks</td><td>Große Entdeckungen von Ebenen, Ausdehnung des Ankernetzes</td></tr><tr><td>Achte Epoche</td><td>Ära der interstellaren Symbiose</td><td>Interstellare Symbiose</td><td>Aufbau des interstellaren Netzwerks→Allgemeine Dimensionserhöhung des Universums</td><td>Universelle Symbiose aller Rassen, Dimensionserhöhung des Universums im Gange</td></tr></tbody></table><h2 id="iii-zeitspanne-und-schlusselindikatoren-jeder-epoche" tabindex="-1">III. Zeitspanne und Schlüsselindikatoren jeder Epoche <a class="header-anchor" href="#iii-zeitspanne-und-schlusselindikatoren-jeder-epoche" aria-label="Permalink to &quot;III. Zeitspanne und Schlüsselindikatoren jeder Epoche&quot;">​</a></h2><p>Da Hengyuanzhou mehrere Ebenen umfasst und die Zeitgeschwindigkeiten zwischen den Ebenen unterschiedlich sind, basiert die Zeitspanne der Epochen auf der Standardzeit der Hauptebene:</p><table tabindex="0"><thead><tr><th>Epoche</th><th>Geschätzte Zeitspanne</th><th>Anker-Abdeckungsrate</th><th>Anteil der Kultivierenden</th><th>Symbiosegrad-Index</th></tr></thead><tbody><tr><td>Vor-Anker-Ära</td><td>Unbekannt (Größenordnung von Milliarden Jahren)</td><td>0%</td><td>&lt;0,01%</td><td>&lt;10</td></tr><tr><td>Ära des Anker-Erwachens</td><td>Tausende von Jahren</td><td>1%→10%</td><td>0,01%→1%</td><td>10→30</td></tr><tr><td>Periode der Etablierung des Symbiose-Systems</td><td>Jahrhunderte</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>Ära der Systemöffnung und -aktivierung</td><td>Jahrhunderte</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>Ära der ersten Dimensionserhöhung</td><td>Jahrzehnte</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>Ära der Allrassen-Republik</td><td>Jahrhunderte</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>Ära der interplanaren Erkundung</td><td>Tausende von Jahren</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>Ära der interstellaren Symbiose</td><td>Andauernd</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>Die Anker-Abdeckungsrate bezieht sich auf den Anteil der Unterregionen von Ebenen, in denen Anker-Hardware eingesetzt wurde; der Anteil der Kultivierenden bezieht sich auf den Anteil der Wesen, die vom formellen Kultivierungssystem abgedeckt werden; der Symbiosegrad-Index ist ein umfassender Indikator zur Messung des Symbiosegrads der Zivilisation mit einer Höchstpunktzahl von 100.</p><h2 id="iv-interne-logik-der-epochenentwicklung" tabindex="-1">IV. Interne Logik der Epochenentwicklung <a class="header-anchor" href="#iv-interne-logik-der-epochenentwicklung" aria-label="Permalink to &quot;IV. Interne Logik der Epochenentwicklung&quot;">​</a></h2><p>Die Epochenentwicklung von Hengyuanzhou ist kein linearer Zeitfluss, sondern ein spiralförmig aufsteigender Evolutionsprozess. Jede Epoche löst die zentralen Widersprüche, die von der vorherigen Epoche hinterlassen wurden, und schafft gleichzeitig die Entwicklungsbedingungen für die nächste Epoche:</p><ul><li>Der grundlegende Widerspruch der Vor-Anker-Ära ist der Widerspruch zwischen Räuberei und Symbiose, dessen Zuspitzung zur Unvermeidlichkeit des Anker-Erwachens führte</li><li>Die Ära des Anker-Erwachens löste das Problem &quot;ob der Anker existiert&quot;, stand jedoch vor der institutionellen Herausforderung &quot;wem der Anker dient&quot;</li><li>Die Periode der Etablierung des Symbiose-Systems schloss den institutionellen Aufbau ab, aber das Monopol der Kultivierungsressourcen schränkte immer noch die Evolution der Massen ein</li><li>Die Ära der Systemöffnung und -aktivierung brach das Kultivierungsmonopol, aber der Sprung der individuellen Fähigkeiten brachte neue ethische und sicherheitstechnische Herausforderungen mit sich</li><li>Die Ära der ersten Dimensionserhöhung verifizierte die Durchführbarkeit der Dimensionserhöhung, aber die Dimensionserhöhung einer einzelnen Ebene reichte nicht aus, um die allgemeine Evolution des Universums voranzutreiben</li><li>Die Ära der Allrassen-Republik vereinheitlichte das Zivilisationssystem, aber es gibt immer noch zahlreiche unkontaktierte Ebenen und Rassen im Universum</li><li>Die Ära der interplanaren Erkundung erweiterte die Grenzen der Zivilisation, aber die verstreuten Ebenen benötigen eine engere interstellare Verbindung</li><li>Die Ära der interstellaren Symbiose zielt letztendlich auf das ultimative Ziel der allgemeinen Dimensionserhöhung des Universums ab</li></ul><h2 id="v-positionierung-der-aktuellen-epoche" tabindex="-1">V. Positionierung der aktuellen Epoche <a class="header-anchor" href="#v-positionierung-der-aktuellen-epoche" aria-label="Permalink to &quot;V. Positionierung der aktuellen Epoche&quot;">​</a></h2><p>Entsprechend dem aktuellen Entwicklungsstand von Hengyuanzhou befindet sich die Zivilisation am kritischen Übergangspunkt von der Dritten Epoche (Periode der Etablierung des Symbiose-Systems) zur Vierten Epoche (Ära der Systemöffnung und -aktivierung). Das Symbiose-System wurde bereits in den Hauptebenen umgesetzt, die Öffnungsarbeit der dreihundert Systeme schreitet umfassend voran, und die 20%-Aktivierungsstrategie hat die Umsetzungsphase erreicht. Mehrere Kerntechnologien auf der Ebene der Gesetzestechnik (Multiplikationsfrucht-Deduktionsmotor, Raumgesetz-Gerät, Kopierspiegel-System) sind vom Labor zur Massenproduktion übergegangen.</p><p>Die zentrale Aufgabe dieser Übergangsperiode ist: Sicherzustellen, dass die Öffnung der dreihundert Systeme wirklich allen Wesen zugutekommt, und gleichzeitig durch die 20%-Aktivierungsstrategie die erste Gruppe der höchsten Wesen der Ebene auszubilden, um ausreichend Energie und Erfahrung für die erste Dimensionserhöhung zu sammeln.</p><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Die Gesamttabelle der Epocheneinteilung ist der makroskopische Rahmen zum Verständnis der historischen Entwicklung von Hengyuanzhou. Sie verdichtet die lange Geschichte des Universums zu acht Epochen mit klarer interner Logik, wobei jede Epoche eine notwendige Stufe zur allgemeinen Dimensionserhöhung des Universums ist. Die nachfolgenden Dokumente werden jede Epoche und die wichtigen Ereignisse darin detailliert ausführen.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>71-Vor-Anker-Ära</li><li>72-Ära des Anker-Erwachens</li><li>76-Meilenstein der ersten Dimensionserhöhung</li></ul>',22)])])}const m=n(d,[["render",s]]);export{c as __pageData,m as default};
